BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"28f89cf8-be4e-4fe7-afcf-2cdaa9093fce","n":1,"title":"أبو تمام والمتنبي حكيمان وأما الشاعر فالبحتري","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"المقارنة النقدية بين حضور الفكر والتخييل والتصوير في القصيدة","passage":"قد تختلف الأحكام النقدية على الشعراء باختلاف معيار الحكم، فلا تجعل عبارة المقارنة حكمًا ثابتًا أو شهادة تاريخية دون التوثق من قائلها. في نموذج مستقل يتناول كاتب فكرة العدالة باستدلال منطقي ويتناولها آخر بصورة حسية؛ كلا النهجين قابل للتحليل.","question":"ما أساس المفاضلة الأدبية المسندة؟","correct":"معيار معلن وشاهد موثق من النص","writing":"اكتب تحليلًا مستقلًا عن «أبو تمام والمتنبي حكيمان وأما الشاعر فالبحتري» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"28f89cf8-be4e-4fe7-afcf-2cdaa9093fce","n":2,"title":"مظاهر التجديد في الشعر العباسي: الموضوعات والأوزان والقوافي","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل صور التجديد في الموضوع والتعبير والموسيقى","passage":"يتطلب وصف التجديد مقارنة شعر أصيل بما سبقه، فقد تتغير موضوعات القصيدة والصور مع استمرار أوزان معروفة. لا يصح افتراض تغيير البحور لمجرد تغير تاريخ النص. نموذج مستقل يبدل طريقة الافتتاح مع بقاء القافية نفسها.","question":"ما دليل التجديد الفني في قصيدة؟","correct":"شاهد مقارن يحدد عنصرًا تغير فعلًا","writing":"اكتب تحليلًا مستقلًا عن «مظاهر التجديد في الشعر العباسي: الموضوعات والأوزان والقوافي» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5df2695a-8474-406b-b48e-fa112a094fcd","n":1,"title":"تلخيص نصوص متنوعة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تلخيص الفكرة الرئيسة والحجج دون نسخ النص","passage":"يلخص القارئ بعباراته ما يدور عليه النص، ثم يرتب الأفكار الفرعية والأمثلة ويحذف التكرار دون تغيير موقف المؤلف. في نص مستقل تقترح طالبة تنظيم مكتبة وتدعم اقتراحها بأسباب؛ يذكر الملخص الاقتراح وسببه ولا ينسخ الجمل كلها.","question":"ما الذي يُحافظ عليه الملخص الجيد؟","correct":"الفكرة المحورية وترابط الحجج","writing":"اكتب تحليلًا مستقلًا عن «تلخيص نصوص متنوعة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5df2695a-8474-406b-b48e-fa112a094fcd","n":2,"title":"شرح نصوص متنوعة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تفسير المفردة في السياق وربط الصورة بالفكرة","passage":"الشرح الجيد يقدم معنى عامًا ثم يحلل لفظًا وتصويرًا وتركيبًا مرتبطًا بالمقصود، ويفصل تفسير المقطع عن رأي القارئ. في عبارة مستقلة «عادت الأصوات إلى الساحة بعد المطر» تُفهم عودة الحركة من قرينة الساحة والمطر.","question":"ماذا يُضيف شرح النص إلى إعادة لفظه؟","correct":"تفسير القرائن والصور وأثرها","writing":"اكتب تحليلًا مستقلًا عن «شرح نصوص متنوعة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5df2695a-8474-406b-b48e-fa112a094fcd","n":3,"title":"كتابة قصص قصيرة وحكايات","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"صياغة حدث وعقدة وتحول وخاتمة مترابطة","passage":"القصة القصيرة تحتاج شخصية وهدفًا وعائقًا وتغيرًا ناتجًا عن اختياراتها، مع زمان ومكان يخدمان الحدث. في قصة أصلية يفقد طالب بطاقة المكتبة فيستدل من سجل الاستعارة حتى يستعيدها؛ تعكس النهاية فعل الشخصية لا المصادفة الخالصة.","question":"ما الذي يربط نهاية القصة بعقدتها؟","correct":"نتيجة أفعال الشخصية لحل المشكلة","writing":"اكتب تحليلًا مستقلًا عن «كتابة قصص قصيرة وحكايات» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5677fba2-e9da-4c7a-bc6b-a8670568ed4e","n":1,"title":"حقيقة الصداقة والصديق","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تعليل الثقة والتعاون واحترام الحدود","passage":"تُقاس الصداقة بالأفعال الداعمة والصدق واحترام الخصوصية أكثر من كثرة المدح. في مثال مستقل يختلف صديقان حول مشروع فيتناقشان دون كشف سر أحدهما؛ يمكن صياغة حجة تذكر السلوك وأثره واستثناء الخلاف الطبيعي.","question":"ما السلوك الدال على الصداقة الموثوقة؟","correct":"المساندة الصادقة واحترام الحدود","writing":"اكتب تحليلًا مستقلًا عن «حقيقة الصداقة والصديق» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5677fba2-e9da-4c7a-bc6b-a8670568ed4e","n":2,"title":"تبدأ حرية الفرد حين تنتهي حرية الآخرين","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"التوازن بين التعبير الشخصي وحقوق الآخرين","passage":"الحرية لا تساوي ترك كل فعل دون أثر؛ يمارس الفرد رأيه مع صون حقوق الآخرين والامتناع عن الإكراه والضرر. في نموذج مستقل يتفق فريق على استخدام قاعة مشتركة بمواعيد عادلة تضمن فرص جميع المشاركين.","question":"ما القاعدة المناسبة لاستخدام القاعة المشتركة؟","correct":"اتفاق يحفظ حقوق الجميع","writing":"اكتب تحليلًا مستقلًا عن «تبدأ حرية الفرد حين تنتهي حرية الآخرين» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5677fba2-e9da-4c7a-bc6b-a8670568ed4e","n":3,"title":"التمييز العنصري وسبل الخلاص منه","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل التمييز والإنصاف باحترام الحقوق","passage":"ينشأ التمييز حين يعامل أشخاص بصورة غير عادلة بسبب أصلهم أو لونهم أو انتمائهم، ويتطلب التصدي له قواعد متساوية وفرصًا عادلة وآلية لإبلاغ الشكاوى. في مثال تدريبي تطبق لجنة نشاط معايير قبول معلنة على جميع المتقدمين.","question":"ما الإجراء الذي يعزز الإنصاف؟","correct":"معايير موحدة شفافة ومراجعة الشكاوى","writing":"اكتب تحليلًا مستقلًا عن «التمييز العنصري وسبل الخلاص منه» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"5677fba2-e9da-4c7a-bc6b-a8670568ed4e","n":4,"title":"مظاهر ثقافة الإنسان المعاصر","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"التفكير النقدي في الثقافة الرقمية والمعرفة","passage":"تتنوع الثقافة المعاصرة بين العلم والإعلام والفنون وأنماط المشاركة، ولا يصح اعتبار استخدام الهاتف دليلًا كافيًا على عمق المعرفة. في مثال مستقل يتحقق متعلم من تاريخ المقال وجهة نشره قبل الاستشهاد به.","question":"أي تصرف يعكس ثقافة تحقق نقدية؟","correct":"فحص المصدر والدليل والتاريخ","writing":"اكتب تحليلًا مستقلًا عن «مظاهر ثقافة الإنسان المعاصر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"877b73c1-e01e-4075-a63a-80ee7fc4c18e","n":1,"title":"من قضايا الشعر في عهد الدولة الرستمية","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحديد موضوع قصيدة مؤرخة في بيئتها التاريخية","passage":"يحتاج الشعر المرتبط بالدولة الرستمية إلى إحالة إلى مخطوط أو مصدر محقق ومعرفة زمن النص؛ فلا تنسب الأبيات أو الآراء السياسية إلى شاعرين من غير تثبت. نموذج مستقل يصور حوارًا عن المسؤولية العامة ولا يمثل قصيدة قديمة.","question":"ما شرط تحديد قضية تاريخية في شعر قديم؟","correct":"تثبيت النص وسياقه ومصدره","writing":"اكتب تحليلًا مستقلًا عن «من قضايا الشعر في عهد الدولة الرستمية» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"877b73c1-e01e-4075-a63a-80ee7fc4c18e","n":2,"title":"نهضة الأدب في عهد الدولة الرستمية","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"الموازنة بين مؤشرات النشاط الأدبي والتوثيق","passage":"لا تُثبت عبارة «نهضة الأدب» كثرة الآثار أو طبيعتها دون مصادر تثبت المدارس والمؤلفين ونوع النصوص. يفيد المتعلم من المقارنة بين مدونات معتمدة وتحديد بيئتها؛ المثال المستقل مجلس قراءة يبين اهتمامًا أدبيًا دون أن يدعي وقوعه تاريخيًا.","question":"كيف يدعم الباحث وصف النهضة الأدبية؟","correct":"شواهد أدبية مؤرخة ومراجع معتمدة","writing":"اكتب تحليلًا مستقلًا عن «نهضة الأدب في عهد الدولة الرستمية» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"877b73c1-e01e-4075-a63a-80ee7fc4c18e","n":3,"title":"الشعر في ظل الصراعات الداخلية على السلطة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"التفريق بين موقف المتكلم والحدث التاريخي","passage":"قد يستخدم الشعر التأييد أو النقد في زمن التنافس السياسي، لكنه لا يصلح وحده إثباتًا لكل التفاصيل التاريخية؛ تُدرس المبالغة والمخاطب واللغة الإقناعية في سياقها. في نص تدريبي يطرح فريقان رأيين حول تنظيم مكتبة.","question":"كيف يفصل الدارس الشعر عن الوقائع؟","correct":"يقارن النص بمصادر تاريخية ويحلل البلاغة","writing":"اكتب تحليلًا مستقلًا عن «الشعر في ظل الصراعات الداخلية على السلطة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"877b73c1-e01e-4075-a63a-80ee7fc4c18e","n":4,"title":"استقلال بلاد المغرب عن الخلافة وانعكاساته في الصراع على السلطة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل انعكاسات التحولات السياسية على الأدب","passage":"تغير مراكز السلطة في المغرب عبر فترات مختلفة، ويلزم تحديد التاريخ والمكان والكيان السياسي قبل ربط قصيدة بواقعة. يقارن المتعلم مصدرًا تاريخيًا بمصدر أدبي ويتحفظ على الأحكام العامة. المشهد المستقل لا يمثل حدثًا سياسيًا.","question":"ما أول خطوة لربط نص بتحول سياسي؟","correct":"تعيين الحقبة وتوثيق الحدث والنص","writing":"اكتب تحليلًا مستقلًا عن «استقلال بلاد المغرب عن الخلافة وانعكاساته في الصراع على السلطة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"a0be93cc-1628-48db-ac39-eaf2d4efdfb4","n":1,"title":"الطبيعة والمدائن الجميلة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"قراءة وصف المدينة والمشهد الطبيعي","passage":"قد يجمع الوصف بين بناء المدينة والماء والبستان والصوت والضوء لخلق إيقاع وجداني. في مثال من ضاديوم «انعكس ضوء المغيب على شرفات البيوت قرب النهر» يربط العمران بالطبيعة ولا ينسب إلى شاعر أندلسي.","question":"ما التفصيل الذي جمع بين المدينة والطبيعة؟","correct":"شرفات البيوت وانعكاس ضوء النهر","writing":"اكتب تحليلًا مستقلًا عن «الطبيعة والمدائن الجميلة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"a0be93cc-1628-48db-ac39-eaf2d4efdfb4","n":2,"title":"خصائص شعر الطبيعة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"المجاز والحواس في التصوير الشعري","passage":"تُدرس خصائص وصف الطبيعة من المشهد المحسوس والتشبيه والتشخيص وعلاقة الألفاظ بعاطفة المتكلم؛ ولا يكفي وجود كلمة «زهرة» للحكم على القصيدة. نموذج مستقل يصور «الندى يلمع كحبات زجاج فوق العشب».","question":"ما الصورة البيانية في «الندى كحبات زجاج»؟","correct":"تشبيه باستعمال أداة الكاف","writing":"اكتب تحليلًا مستقلًا عن «خصائص شعر الطبيعة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"a0be93cc-1628-48db-ac39-eaf2d4efdfb4","n":3,"title":"رثاء الممالك والمدن","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل فقد المكان وعلاقته بالذاكرة الجماعية","passage":"يجمع رثاء المدن أحيانًا بين صور العمران الماضي وأثر التحول أو الفقد على المتكلم؛ لا تُنسب أخبار المدن من عنوان القصيدة. في نص مستقل يتذكر راو ساحة تحولت مع السنوات، فيقارنها بصورة احتفظ بها.","question":"ما الشعور المركزي في مثال استذكار الساحة؟","correct":"الأسى على تغير المكان","writing":"اكتب تحليلًا مستقلًا عن «رثاء الممالك والمدن» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"a0be93cc-1628-48db-ac39-eaf2d4efdfb4","n":4,"title":"الفتنة البربرية وآثارها في الشعر والأدب","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"التمييز بين التسمية التاريخية وشواهد الأدب","passage":"تحتاج الأحداث المعروفة في بعض المصادر باسم «الفتنة البربرية» إلى تحديد زمنها ورواياتها المختلفة وتجنب تعميم الصراع على جميع الناس. يؤخذ النص الأدبي شاهدًا على منظور صاحبه لا سجلًا كاملًا للحادثة.","question":"كيف تُدرس روايات نزاع تاريخي بإنصاف؟","correct":"تحديد المصدر والسياق واختلاف الروايات","writing":"اكتب تحليلًا مستقلًا عن «الفتنة البربرية وآثارها في الشعر والأدب» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":1,"title":"النزعة العقلية في الشعر","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل بناء الحجة والتأمل في الصورة","passage":"قد يجمع النص الشعري بين الصورة الفنية والتفكير المجرد أو التعليل، وتظهر النزعة العقلية في ترتيب المعاني والمقارنة والاستنتاج. مثال مستقل يقارن كاتب بين اتخاذ قرار متسرع وآخر بعد فحص الأدلة، دون أن يمثل بيتًا عباسيًا.","question":"أين تظهر النزعة العقلية في النموذج؟","correct":"في التعليل والمقارنة وصولًا لاستنتاج","writing":"اكتب تحليلًا مستقلًا عن «النزعة العقلية في الشعر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":2,"title":"أثر النزعة العقلية في القصيدة العربية","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تقويم دور الفكر في بنية القصيدة","passage":"يمكن للأفكار المجردة أن تؤثر في تنظيم البيت والصورة والحكمة، لكن لا يُحكم على جودة الشعر من كثرة المصطلحات الفلسفية. يحتاج التحليل شاهدًا من قصيدة موثقة يوضح التناسب بين الحجة والإيقاع.","question":"ما الدليل على أثر التفكير في القصيدة؟","correct":"شاهد يربط الاستدلال بالبناء الشعري","writing":"اكتب تحليلًا مستقلًا عن «أثر النزعة العقلية في القصيدة العربية» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":3,"title":"الشعوبية وأثرها في الأدب","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"قراءة الجدل الثقافي بعيدًا عن التعميم","passage":"تتناول مصادر تاريخية جدل الانتماء والمفاضلة بين جماعات في سياقات عباسية متنوعة؛ يجب فصل خطاب الأديب عن كل أفراد الجماعة وتجنب إحياء التمييز. يراجع الطالب نصًا صحيح النسبة ويحلل حجته وقواعد الاستدلال.","question":"ما الذي يمنع تعميم رأي الكاتب على جماعته؟","correct":"تمييز صوت النص عن جميع الأفراد","writing":"اكتب تحليلًا مستقلًا عن «الشعوبية وأثرها في الأدب» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":4,"title":"الشعوبية وصراع الحضارات","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"مناقشة تعدد الثقافات ومغالطات المفاضلة","passage":"تتبادل الثقافات التأثير في اللغة والمعارف، بينما قد تتضمن بعض النصوص القديمة ادعاءات تفوق غير مسندة. تحليلها تاريخيًا لا يعني تبني تلك المواقف؛ يفحص المتعلم الدليل والسياق ويتجنب اختزال حضارة في رأي واحد.","question":"كيف تقرأ مفاضلة ثقافية في نص قديم؟","correct":"بفحص الحجة وسياقها دون تعميم","writing":"اكتب تحليلًا مستقلًا عن «الشعوبية وصراع الحضارات» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":5,"title":"المجون والزندقة","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تمييز المصطلحات الأدبية والتاريخية بحذر","passage":"تظهر المصطلحات في بعض أخبار العصر العباسي، لكن أحكام الاعتقاد المنسوبة إلى شخص تحتاج توثيقًا ولا تؤخذ من قصيدة مجازية وحدها. يركز التدريب على اختلاف السياق بين وصف لهو اجتماعي وحكم فكري أو ديني غير مثبت.","question":"لماذا لا يكفي بيت مجازي لإثبات اعتقاد صاحبه؟","correct":"لأن الصورة لا تعادل اعترافًا تاريخيًا موثقًا","writing":"اكتب تحليلًا مستقلًا عن «المجون والزندقة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":6,"title":"حياة اللهو والمجون","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تأمل وصف أنماط العيش دون اختلاق سيرة","passage":"تتناول نصوص بعض العصور مظاهر الترف واللهو بأصوات متباينة؛ قد يكون الوصف نقدًا أو سخرية لا إقرارًا من المؤلف. مثال مستقل يصف راو ضياع يومه بين أنشطة ترفيهية ثم يراجع أولوياته، وليس خبرًا عباسيًا.","question":"ما الذي يحدد موقف المتكلم من اللهو؟","correct":"قرائن اللغة والسياق ونبرة النص","writing":"اكتب تحليلًا مستقلًا عن «حياة اللهو والمجون» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":7,"title":"شعر الزهد","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"استخراج الموعظة والتأمل في المصير","passage":"يعتمد بعض شعر الزهد على التذكير بمرور الزمن ومحاسبة النفس وتقليل التعلق بالمظاهر؛ لا يعني ذلك أن كل نص يحتوي على حزن قصيدة زهد. في مثال مستقل يختار شخص مساعدة جاره على اقتناء ما لا يحتاجه.","question":"ما القيمة الأقرب إلى الزهد في النموذج؟","correct":"تقديم العمل النافع على المباهاة","writing":"اكتب تحليلًا مستقلًا عن «شعر الزهد» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":8,"title":"الدعوة إلى الإصلاح والميل إلى الزهد","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل العلاقة بين النقد الاجتماعي ومحاسبة النفس","passage":"قد تربط قصيدة بين رفض الإسراف والدعوة إلى إصلاح السلوك عبر المقابلة والتوجيه. لا تصح نسبة وصية إلى شاعر بعينه دون أبيات معتمدة. نص مستقل يراجع فيه مسؤول نفقات فريق ويختار توجيه فائض لوسيلة تعليمية.","question":"ما دليل الإصلاح في مثال النفقات؟","correct":"توجيه الموارد إلى منفعة مشتركة","writing":"اكتب تحليلًا مستقلًا عن «الدعوة إلى الإصلاح والميل إلى الزهد» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":9,"title":"نشاط النثر","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"التمييز بين المقامة والرسالة والخطبة","passage":"يتنوع النثر العباسي في الرسائل والخطابة والمحاورات وغيرها، ويُدرس من خلال الغرض والمخاطب وبنية الحجة. في مثال مستقل تتضمن رسالة طلبًا موجهًا، بينما تعتمد مناظرة تبادل الاعتراض والرد.","question":"ما السمة الأبرز في المناظرة؟","correct":"تبادل الحجج والردود بين أطراف","writing":"اكتب تحليلًا مستقلًا عن «نشاط النثر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"15ee53fb-0f01-45e8-9fae-03a607107ab7","n":10,"title":"الحركة العلمية وأثرها في الفكر والأدب","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"فهم أثر الترجمة والتعليم في الأسلوب","passage":"يمكن أن ينعكس تداول المعرفة على المصطلحات وبناء الحجة في النثر والشعر، لكن نسبة كتاب تاريخي إلى مترجم معين تتطلب مرجعًا. نموذج تدريبي يراجع فريق مصطلحًا علميًا ويوازن بين الدقة ووضوح الصياغة.","question":"ما المعيار المناسب لترجمة مصطلح علمي؟","correct":"دقة المعنى ووضوح استعماله في السياق","writing":"اكتب تحليلًا مستقلًا عن «الحركة العلمية وأثرها في الفكر والأدب» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"d1b53d96-348e-46ac-b422-de3418731cab","n":1,"title":"الحكمة والفلسفة في الشعر","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تمييز الفكرة العامة من الحجة المجردة","passage":"قد يتضمن الشعر تأملًا في الاختيار والزمان والعلم في صورة حكمة، ويحتاج الفهم إلى تحليل العلاقة بين الفكرة والتمثيل دون الاكتفاء بعبارة مؤثرة. نموذج مستقل «تؤدي المراجعة إلى قرار أهدأ» حكم قابل للنقاش لا بيت منسوب.","question":"كيف تقيّم حكمة واردة في نص شعري؟","correct":"تفسر الفكرة وتبحث عن قرائن وسياق","writing":"اكتب تحليلًا مستقلًا عن «الحكمة والفلسفة في الشعر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"d1b53d96-348e-46ac-b422-de3418731cab","n":2,"title":"الحركة العقلية والفلسفية في الحواضر العربية","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل انتشار النقاش العلمي والنصوص الموثقة","passage":"تختلف الحياة الفكرية باختلاف المدن والمؤسسات والأزمنة؛ لذا لا يُنسب رأي إلى مدينة بأكملها. يبحث القارئ عن مصدر أدبي وفكري مؤرخ ثم يدرس طريقة طرح السؤال والاعتراض.","question":"ما الشرط لتحديد أثر مدينة في الفكر؟","correct":"مصادر مؤرخة ونماذج نصية محددة","writing":"اكتب تحليلًا مستقلًا عن «الحركة العقلية والفلسفية في الحواضر العربية» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"d1b53d96-348e-46ac-b422-de3418731cab","n":3,"title":"الشكوى واضطراب أحوال المجتمع","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"قراءة الشكوى في صوت المتكلم وأدلتها","passage":"قد يصور الشعر متكلمًا يشكو ضيقًا أو ظلمًا أو تغيرًا في العلاقات؛ لا تتحول عاطفته تلقائيًا إلى إحصاء عن مجتمع بأكمله. نموذج مستقل يعترض طالب على توزيع غير متوازن للمهام ويقدم أمثلة.","question":"ما الذي يميز الشكوى المعللة؟","correct":"ذكر وقائع أو قرائن محددة","writing":"اكتب تحليلًا مستقلًا عن «الشكوى واضطراب أحوال المجتمع» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"2e49cb28-aa90-4202-9fe6-2f2b183755e6","uid":"d1b53d96-348e-46ac-b422-de3418731cab","n":4,"title":"الحياة الاجتماعية ومظاهر الظلم","old":"DADYOOM_DZ_SECONDARY_OFFICIAL_DETAIL","focus":"تحليل النصوص الاجتماعية مع صون كرامة الأشخاص","passage":"يمكن للنثر أو الشعر نقد تفاوت الفرص وإساءة استخدام السلطة، لكن القراءة المتزنة تعرض الدليل ووجهة النظر ولا تخلط الواقعة التاريخية بالتخييل. يطلب متدرب مراجعة معيار اختيار غير واضح في مثال مستقل.","question":"ما الإجراء المنصف لتقييم شكوى؟","correct":"مراجعة المعايير والوقائع دون أحكام مسبقة","writing":"اكتب تحليلًا مستقلًا عن «الحياة الاجتماعية ومظاهر الظلم» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"a98586f7-5e98-469a-b842-503b3a6626de","n":1,"title":"النزعة العقلية في الشعر","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحليل بناء الحجة والتأمل في الصورة","passage":"قد يجمع النص الشعري بين الصورة الفنية والتفكير المجرد أو التعليل، وتظهر النزعة العقلية في ترتيب المعاني والمقارنة والاستنتاج. مثال مستقل يقارن كاتب بين اتخاذ قرار متسرع وآخر بعد فحص الأدلة، دون أن يمثل بيتًا عباسيًا.","question":"أين تظهر النزعة العقلية في النموذج؟","correct":"في التعليل والمقارنة وصولًا لاستنتاج","writing":"اكتب تحليلًا مستقلًا عن «النزعة العقلية في الشعر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"a98586f7-5e98-469a-b842-503b3a6626de","n":2,"title":"الدعوة إلى التجديد والقضاء على القديم","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"التمييز بين التجديد النافع ورفض الموروث بلا دليل","passage":"قد تدعو قصيدة إلى تبديل أسلوب أو موضوع، لكن وصف كل موروث بأنه غير صالح مغالطة؛ يحتاج الناقد إلى مقارنة فعلية في البناء والصورة واللغة. في مثال مستقل يعيد كاتب ترتيب رواية قديمة من منظور شخصية جانبية.","question":"ما الدليل على تجديد بناء النص؟","correct":"تغير طريقة السرد مع بيان أثره","writing":"اكتب تحليلًا مستقلًا عن «الدعوة إلى التجديد والقضاء على القديم» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"a98586f7-5e98-469a-b842-503b3a6626de","n":3,"title":"شعر الزهد","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"استخراج الموعظة والتأمل في المصير","passage":"يعتمد بعض شعر الزهد على التذكير بمرور الزمن ومحاسبة النفس وتقليل التعلق بالمظاهر؛ لا يعني ذلك أن كل نص يحتوي على حزن قصيدة زهد. في مثال مستقل يختار شخص مساعدة جاره على اقتناء ما لا يحتاجه.","question":"ما القيمة الأقرب إلى الزهد في النموذج؟","correct":"تقديم العمل النافع على المباهاة","writing":"اكتب تحليلًا مستقلًا عن «شعر الزهد» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"a98586f7-5e98-469a-b842-503b3a6626de","n":4,"title":"التقليد والتجديد في النتاج الشعري العباسي","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"مقارنة الاستمرار والتحول في صورة القصيدة","passage":"يمكن للشاعر أن يحتفظ بالوزن والقافية ويجدد في الصورة أو الموضوع، فلا يصح جعل التقليد والتجديد حكمين مطلقين. يعتمد التدريب على مقارنة مطلعين صحيحَي النسبة وملاحظة البناء.","question":"ما المثال الأقرب لتجديد داخل شكل موروث؟","correct":"صورة جديدة في وزن وقافية مألوفين","writing":"اكتب تحليلًا مستقلًا عن «التقليد والتجديد في النتاج الشعري العباسي» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"a98586f7-5e98-469a-b842-503b3a6626de","n":5,"title":"نشاط النثر","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"التمييز بين المقامة والرسالة والخطبة","passage":"يتنوع النثر العباسي في الرسائل والخطابة والمحاورات وغيرها، ويُدرس من خلال الغرض والمخاطب وبنية الحجة. في مثال مستقل تتضمن رسالة طلبًا موجهًا، بينما تعتمد مناظرة تبادل الاعتراض والرد.","question":"ما السمة الأبرز في المناظرة؟","correct":"تبادل الحجج والردود بين أطراف","writing":"اكتب تحليلًا مستقلًا عن «نشاط النثر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"8125dd97-a2d0-40ba-ac5a-aea626bd13fe","n":1,"title":"وصف الطبيعة الجميلة","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحديد عناصر المشهد وعاطفته","passage":"تحلل نصوص الوصف باستخراج الحواس والتشبيه وحركة المشهد وعلاقة المكان بالشعور؛ لا تُنسب عبارات ضاديوم إلى شاعر قديم. المثال المستقل «انتشر لون الشفق على ماء الجدول» يصور الضوء والحركة.","question":"ما الحاسة التي يبرزها لون الشفق؟","correct":"البصر","writing":"اكتب تحليلًا مستقلًا عن «وصف الطبيعة الجميلة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"8125dd97-a2d0-40ba-ac5a-aea626bd13fe","n":2,"title":"رثاء الممالك","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تفسير الحنين والفقد في سياقه التاريخي","passage":"قد يتناول الشاعر تغير مُلك أو مكان، ويجمع التاريخ المتحقق والانفعال الشخصي، لكن يجب تحديد النص وزمنه قبل نسبة أحداث إليه. في نموذج مستقل يتأمل راو قصرًا قديمًا تحوّل إلى متحف ويتذكر حياة سابقة.","question":"أي عاطفة تناسب مثال القصر القديم؟","correct":"الحنين الممزوج بالأسى","writing":"اكتب تحليلًا مستقلًا عن «رثاء الممالك» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"8125dd97-a2d0-40ba-ac5a-aea626bd13fe","n":3,"title":"الموشحات","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تمييز البنية الغنائية المتنوعة عن القصيدة العمودية","passage":"للموشح الأندلسي بنية قد تتضمن أقفالًا وأغصانًا وخرجة بحسب النوع، ولا يجوز افتراض تطابق البنية في جميع الموشحات. يفحص المتعلم مقطعًا صحيح النص ليرى التناظر الصوتي وتغير القوافي.","question":"كيف نحدد بنية موشح معتمد؟","correct":"نفحص الأقفال والأغصان والخرجة في نص موثق","writing":"اكتب تحليلًا مستقلًا عن «الموشحات» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"7f9fcdae-6ea1-48b8-b9bb-a5ca0ff9d542","n":1,"title":"من قضايا الشعر في عهد الدولة الرستمية","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحديد موضوع قصيدة مؤرخة في بيئتها التاريخية","passage":"يحتاج الشعر المرتبط بالدولة الرستمية إلى إحالة إلى مخطوط أو مصدر محقق ومعرفة زمن النص؛ فلا تنسب الأبيات أو الآراء السياسية إلى شاعرين من غير تثبت. نموذج مستقل يصور حوارًا عن المسؤولية العامة ولا يمثل قصيدة قديمة.","question":"ما شرط تحديد قضية تاريخية في شعر قديم؟","correct":"تثبيت النص وسياقه ومصدره","writing":"اكتب تحليلًا مستقلًا عن «من قضايا الشعر في عهد الدولة الرستمية» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"7f9fcdae-6ea1-48b8-b9bb-a5ca0ff9d542","n":2,"title":"الشعر في ظل الصراعات الداخلية على السلطة","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"التفريق بين موقف المتكلم والحدث التاريخي","passage":"قد يستخدم الشعر التأييد أو النقد في زمن التنافس السياسي، لكنه لا يصلح وحده إثباتًا لكل التفاصيل التاريخية؛ تُدرس المبالغة والمخاطب واللغة الإقناعية في سياقها. في نص تدريبي يطرح فريقان رأيين حول تنظيم مكتبة.","question":"كيف يفصل الدارس الشعر عن الوقائع؟","correct":"يقارن النص بمصادر تاريخية ويحلل البلاغة","writing":"اكتب تحليلًا مستقلًا عن «الشعر في ظل الصراعات الداخلية على السلطة» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"74338716-7407-48cd-8dde-26cd54ad9fb8","n":1,"title":"الحكمة والفلسفة في الشعر","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تمييز الفكرة العامة من الحجة المجردة","passage":"قد يتضمن الشعر تأملًا في الاختيار والزمان والعلم في صورة حكمة، ويحتاج الفهم إلى تحليل العلاقة بين الفكرة والتمثيل دون الاكتفاء بعبارة مؤثرة. نموذج مستقل «تؤدي المراجعة إلى قرار أهدأ» حكم قابل للنقاش لا بيت منسوب.","question":"كيف تقيّم حكمة واردة في نص شعري؟","correct":"تفسر الفكرة وتبحث عن قرائن وسياق","writing":"اكتب تحليلًا مستقلًا عن «الحكمة والفلسفة في الشعر» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]},{"cid":"87ba9e9f-59a4-49b3-992a-d4992066dc66","uid":"74338716-7407-48cd-8dde-26cd54ad9fb8","n":2,"title":"الشكوى واضطراب أحوال المجتمع","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"قراءة الشكوى في صوت المتكلم وأدلتها","passage":"قد يصور الشعر متكلمًا يشكو ضيقًا أو ظلمًا أو تغيرًا في العلاقات؛ لا تتحول عاطفته تلقائيًا إلى إحصاء عن مجتمع بأكمله. نموذج مستقل يعترض طالب على توزيع غير متوازن للمهام ويقدم أمثلة.","question":"ما الذي يميز الشكوى المعللة؟","correct":"ذكر وقائع أو قرائن محددة","writing":"اكتب تحليلًا مستقلًا عن «الشكوى واضطراب أحوال المجتمع» يتضمن فكرة وشاهدًا موثقًا إن كان موضوعًا تاريخيًا، وتفسيرًا وأثرًا ونتيجة. وضّح مصدر الشاهد وافصل المثال التدريبي من نص الكتاب.","wrong":["الاكتفاء بعنوان الدرس دون شاهد","نسبة مثال من إنشائنا إلى نص رسمي","اعتبار الانطباع الشخصي دليلًا قاطعًا"]}]'::jsonb)
    AS x(cid uuid,uid uuid,n integer,title text,old text,focus text,passage text,question text,correct text,writing text,wrong text[])
  LOOP
    SELECT l.id,l.content INTO STRICT target_lesson_id,prior_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id
    JOIN public.curricula cu ON cu.id=g.curriculum_id
    JOIN public.countries co ON co.id=cu.country_id
    WHERE co.code='DZ' AND cu.id=r.cid AND g.grade_number=11 AND u.id=r.uid
      AND u.semester IS NULL AND l.sort_order=r.n AND l.title=r.title
      AND l.status='published'
    FOR UPDATE OF l;

    SELECT count(*) INTO checked FROM public.student_lesson_progress
      WHERE lesson_id=target_lesson_id;
    IF checked<>0 THEN RAISE EXCEPTION 'ALGERIA_G11_ACTIVE_PROGRESS_FOR_%',r.title; END IF;
    SELECT count(*) INTO checked FROM public.lesson_activity_attempts at
      JOIN public.lesson_activities a ON a.id=at.activity_id
      WHERE a.lesson_id=target_lesson_id;
    IF checked<>0 THEN RAISE EXCEPTION 'ALGERIA_G11_ACTIVE_ATTEMPTS_FOR_%',r.title; END IF;
    IF char_length(coalesce(prior_content,'')) >= 350 THEN
       RAISE EXCEPTION 'ALGERIA_G11_ALREADY_HAS_FULL_CONTENT_%',r.title;
    END IF;
    SELECT count(*) INTO existing FROM public.lesson_activities
       WHERE lesson_id=target_lesson_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
    IF existing<>3 THEN
       RAISE EXCEPTION 'ALGERIA_G11_EXPECTED_3_ACTIVITY_PLACEHOLDERS_%_GOT_%',r.title,existing;
    END IF;

    UPDATE public.lessons SET
      content='ضاديوم — إثراء أصلي مستقل للسنة الثانية ثانوي في الجزائر. النص تدريبي غير منقول من الكتاب، وتظل مطابقة عنوان الدرس بالإصدار الوزاري معلقة.'
       ||E'\n\n'||'الموضوع: '||r.title
       ||E'\n\n'||'الهدف: '||r.focus||'.'
       ||E'\n\n'||'شرح وتطبيق غير منسوب: '||r.passage
       ||E'\n\n'||'استراتيجية القراءة: حدّد الفكرة المركزية، ثم استخرج قرينة من النص الذي تقرؤه بالفعل، وفسر أثر صياغتها، وبعد ذلك قارن بين تفسيرين في ضوء الدليل.'
       ||E'\n\n'||'تقويم فهم: '||r.question
       ||E'\n\n'||'نشاط تحليلي: '||r.writing
       ||E'\n\n'||'تمايز وتغذية راجعة: للمبتدئ مفردات مساعدة وأمثلة قصيرة؛ للمتوسط ترتيب شواهد ومناقشة أثرها؛ وللمتقدم نقد دليل مخالف وبناء استنتاج منصف. يحتاج الإنتاج الكتابي إلى مراجعة معلم، ولا تُنسب أمثلة ضاديوم إلى شعراء أو كتب وزارية.'
       ||E'\n\n'||'المحتوى السابق محفوظ: '||coalesce(prior_content,''),
       updated_at=now()
     WHERE id=target_lesson_id;

    UPDATE public.lesson_activities SET
      prompt='اقرأ المثال المستقل ثم حدد الفكرة الأساسية وقرينة لغوية تدعمها.',
      content=content||jsonb_build_object('origin','DADYOOM_DZ_G11_ORIGINAL_ENRICHMENT_43_20261009','previousOrigin',r.old,
        'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_lesson_id AND activity_type='reading' AND content->>'origin'=r.old
      AND answer='{}'::jsonb;

    UPDATE public.lesson_activities SET prompt=r.question,
      content=content||jsonb_build_object('origin','DADYOOM_DZ_G11_ORIGINAL_ENRICHMENT_43_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
          WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
          WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
          WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
          ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
      answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_lesson_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

    UPDATE public.lesson_activities SET prompt=r.writing,
      content=content||jsonb_build_object('origin','DADYOOM_DZ_G11_ORIGINAL_ENRICHMENT_43_20261009','previousOrigin',r.old,
       'text',r.writing,'notOfficialBook',true,'sourceVerification','pending','humanReviewRequired',true)
    WHERE lesson_id=target_lesson_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

    SELECT count(*) INTO existing FROM public.lesson_activities
      WHERE lesson_id=target_lesson_id AND content->>'origin'='DADYOOM_DZ_G11_ORIGINAL_ENRICHMENT_43_20261009';
    IF existing<>3 THEN
      RAISE EXCEPTION 'ALGERIA_G11_ACTIVITY_UPDATE_FAILED_%_COUNT_%',r.title,existing;
    END IF;
  END LOOP;
END
$dadyoom$;